var catalogo_default = createCatalogHandler({
  getStore: () => getStore({ name: "raiden-shop-catalogo-v1", consistency: "strong" }),
  seed: catalogo_seed_default,
  getPassword: () => process.env.CATALOGO_ADMIN_PASSWORD,
  loadLive: async () => {
    const base = process.env.URL;
    if (!base) throw new Error("URL de Netlify no disponible.");
    const response = await fetch(new URL("/.netlify/functions/loyverse-items", base), {
      cache: "no-store",
      headers: { "X-Raiden-Snapshot": "1" },
      signal: AbortSignal.timeout(45e3)
    });
    if (!response.ok) throw new Error("Fall\xF3 Loyverse.");
    return response.json();
  }
});
export {
  catalogo_default as default
};
